                {'changed_param': '"main_color"', 'target_param': '"color_rope"',          'copy_from': '"main_color"', 'only_if_empty': 'true'},
                {'changed_param': '"main_color"', 'target_param': '"color_shirit"',        'copy_from': '"main_color"', 'only_if_empty': 'true'},
